pub enum PlicPeripheral {
    /// Unknown Peripheral
    Unknown = 0,
    /// rv_timer
    RvTimer = 1,
    /// aon_timer_aon
    AonTimerAon = 2,
    /// dma
    Dma = 3,
    /// mbx0
    Mbx0 = 4,
    /// mbx1
    Mbx1 = 5,
    /// mbx2
    Mbx2 = 6,
    /// mbx3
    Mbx3 = 7,
    /// mbx4
    Mbx4 = 8,
    /// mbx5
    Mbx5 = 9,
    /// mbx_pcie0
    MbxPcie0 = 10,
    /// ac_range_check
    AcRangeCheck = 11,
}

impl TryFrom<u32> for PlicPeripheral {
    type Error = u32;
    fn try_from(val: u32) -> Result<Self, Self::Error> {
        match val {
            0 => Ok(Self::Unknown),
            1 => Ok(Self::RvTimer),
            2 => Ok(Self::AonTimerAon),
            3 => Ok(Self::Dma),
            4 => Ok(Self::Mbx0),
            5 => Ok(Self::Mbx1),
            6 => Ok(Self::Mbx2),
            7 => Ok(Self::Mbx3),
            8 => Ok(Self::Mbx4),
            9 => Ok(Self::Mbx5),
            10 => Ok(Self::MbxPcie0),
            11 => Ok(Self::AcRangeCheck),
            _ => Err(val),
        }
    }
}

